<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$s=$db->query("SELECT (SELECT COUNT(*) FROM marketing_campaigns WHERE status='active') active_campaigns,(SELECT COUNT(*) FROM marketing_events WHERE occurred_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) events_30d,(SELECT COUNT(*) FROM marketing_conversions WHERE converted_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) conversions_30d,(SELECT COALESCE(SUM(value),0) FROM marketing_conversions WHERE converted_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) revenue_30d,(SELECT COUNT(*) FROM lead_marketing_scores WHERE grade IN ('hot','qualified')) hot_leads,(SELECT COALESCE(SUM(budget),0) FROM marketing_campaigns WHERE status IN ('active','completed')) total_budget")->fetch();$campaigns=$db->query("SELECT c.*,COALESCE((SELECT COUNT(*) FROM marketing_events e WHERE e.campaign_id=c.id),0) events,COALESCE((SELECT COUNT(*) FROM marketing_conversions x WHERE x.campaign_id=c.id),0) conversions,COALESCE((SELECT SUM(value) FROM marketing_conversions x WHERE x.campaign_id=c.id),0) revenue FROM marketing_campaigns c ORDER BY c.created_at DESC LIMIT 25")->fetchAll();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing Analytics</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Marketing Analytics & ROI</h1><div class="row g-3 mb-4"><?php foreach([['Active Campaigns',$s['active_campaigns']],['Events 30d',$s['events_30d']],['Conversions 30d',$s['conversions_30d']],['Revenue 30d',$s['revenue_30d']],['Hot/Qualified Leads',$s['hot_leads']],['Campaign Budget',$s['total_budget']]] as $x):?><div class="col-md-4"><div class="card"><div class="card-body"><small><?=$e($x[0])?></small><h2><?=$e($x[1])?></h2></div></div></div><?php endforeach;?></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Campaign</th><th>Status</th><th>Events</th><th>Conversions</th><th>Revenue</th><th>ROI</th></tr></thead><tbody><?php foreach($campaigns as $c):$roi=(float)$c['budget']>0?(((float)$c['revenue']-(float)$c['budget'])/(float)$c['budget'])*100:0;?><tr><td><?=$e($c['name'])?></td><td><?=$e($c['status'])?></td><td><?=$e($c['events'])?></td><td><?=$e($c['conversions'])?></td><td><?=$e($c['currency'].' '.$c['revenue'])?></td><td><?=$e(number_format($roi,2))?>%</td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>